create or replace function public.record_visitor_session(
	p_id text, p_visitor_id text, p_source text default null,
	p_medium text default null, p_campaign text default null,
	p_content text default null, p_device_model text default null,
	p_device_kind text default null, p_os text default null,
	p_browser text default null
)
returns table(today_count bigint, month_count bigint)
language plpgsql security definer set search_path = public
as $$
begin
	if length(p_id) not between 1 and 128 or length(p_visitor_id) not between 1 and 128 then
		raise exception 'invalid visitor session';
	end if;
	insert into public.visitor_sessions (
		id, visitor_id, visited_day, visited_month, source, medium, campaign,
		content, device_model, device_kind, os, browser
	) values (
		p_id, p_visitor_id, current_date, to_char(current_date, 'YYYY-MM'),
		nullif(left(p_source, 100), ''), nullif(left(p_medium, 100), ''),
		nullif(left(p_campaign, 100), ''), nullif(left(p_content, 100), ''),
		nullif(left(p_device_model, 150), ''), nullif(left(p_device_kind, 30), ''),
		nullif(left(p_os, 100), ''), nullif(left(p_browser, 100), '')
	) on conflict (id) do nothing;
	return query select
		(select count(*) from public.visitor_sessions where visited_day = current_date),
		(select count(*) from public.visitor_sessions where visited_month = to_char(current_date, 'YYYY-MM'));
end;
$$;
revoke all on function public.record_visitor_session(text, text, text, text, text, text, text, text, text, text) from public;
grant execute on function public.record_visitor_session(text, text, text, text, text, text, text, text, text, text) to anon, authenticated;

create or replace function public.get_funnel_analytics()
returns table(data jsonb)
language plpgsql security definer set search_path = public
as $$
declare
	result jsonb := jsonb_build_object('visits', (select count(*) from public.visitor_sessions), 'leads', (select count(*) from public.leads), 'bySource', '{}'::jsonb, 'bySourceStats', '{}'::jsonb, 'byVariant', '{}'::jsonb);
	item record; source_name text; visit_count bigint; lead_count bigint; variant_name text; variant_lead_count bigint;
begin
	if not public.is_funnel_admin() then raise exception 'admin access required'; end if;
	for item in select coalesce(nullif(source, ''), 'direct') as source_name, count(*) as visit_count from public.visitor_sessions group by 1 loop
		source_name := item.source_name; visit_count := item.visit_count;
		select count(*) into lead_count from public.leads where coalesce(nullif(utm_source, ''), nullif(traffic_ads_source, ''), 'direct') = source_name;
		result := jsonb_set(result, array['bySource', source_name], to_jsonb(visit_count), true);
		result := jsonb_set(result, array['bySourceStats', source_name], jsonb_build_object('visits', visit_count, 'leads', lead_count), true);
	end loop;
	for item in select variant, count(*) as lead_count from public.leads where nullif(variant, '') is not null group by 1 loop
		variant_name := item.variant; variant_lead_count := item.lead_count;
		result := jsonb_set(result, array['byVariant', variant_name], jsonb_build_object('visits', 0, 'leads', variant_lead_count), true);
	end loop;
	return query select result;
end;
$$;
revoke all on function public.get_funnel_analytics() from public;
grant execute on function public.get_funnel_analytics() to authenticated;

create or replace function public.reset_funnel_analytics()
returns void language plpgsql security definer set search_path = public as $$
begin
	if not public.is_funnel_admin() then raise exception 'admin access required'; end if;
	-- Chỉ reset số liệu lượt truy cập, KHÔNG đụng tới bảng leads (CRM); muốn xóa lead hãy dùng clear_funnel_leads().
	delete from public.visitor_sessions where true;
	insert into public.funnel_analytics (id, data, updated_at) values (1, '{"visits":0,"leads":0,"bySource":{},"bySourceStats":{},"byVariant":{}}'::jsonb, now()) on conflict (id) do update set data = excluded.data, updated_at = excluded.updated_at;
end;
$$;
revoke all on function public.reset_funnel_analytics() from public;
grant execute on function public.reset_funnel_analytics() to authenticated;

