"},{"stat":"80%","text":"Chỉ 20% lý thuyết. Bạn làm việc trực tiếp trên dây chuyền, máy móc và công nghệ mới nhất.","title":"80% thực hành"},{"stat":"15-30tr","text":"Vừa học vừa làm, thu nhập 15-30 triệu/tháng, đủ chi phí sinh hoạt và gửi về gia đình.","title":"Lương cứng mỗi tháng"},{"stat":"Bằng","text":"Bằng Cao đẳng chính quy được công nhận quốc tế, mở đường ở lại làm việc hoặc học tiếp.","title":"Cao đẳng chính quy quốc tế"}],"majorsHeading":"8 ngành nghề phát triển trong 5-20 năm tới","majorsDescription":"Các lựa chọn bám sát chuyển dịch công nghệ, sản xuất và thương mại giữa Việt Nam – Trung Quốc.","majorNames":["Công nghệ Ô tô điện","Công nghệ Drone (UAV)","Thương mại điện tử","Logistics & Chuỗi cung ứng","Kỹ thuật Điện tử","IoT - Internet vạn vật","Cơ khí tự động hóa","Hán ngữ thương mại"],"majorIcons":["🚗","🛸","🛒","🚚","🔌","📡","⚙️","🀄"],"majorDescriptions":["Đón đầu xu hướng điện hóa giao thông, pin thế hệ mới và hệ sinh thái xe thông minh.","Phát triển cùng nhu cầu UAV trong nông nghiệp, vận chuyển, khảo sát và cứu hộ.","Mở rộng theo thương mại xuyên biên giới, bán hàng đa kênh và vận hành bằng dữ liệu.","Giữ vai trò cốt lõi khi chuỗi cung ứng khu vực ngày càng tự động hóa và kết nối sâu.","Là nền tảng cho thiết bị thông minh, năng lượng sạch, robot và sản xuất công nghệ cao.","Kết nối nhà máy, đô thị và thiết bị thông minh trong nền kinh tế số tương lai.","Thúc đẩy nhà máy thông minh, robot cộng tác và dây chuyền sản xuất ít phụ thuộc lao động tay chân.","Tạo lợi thế trong thương mại, dịch vụ và hợp tác doanh nghiệp Việt Nam – Trung Quốc."],"expertsHeading":"Đội ngũ chuyên gia tư vấn","expertsDescription":"Đồng hành từ lúc chọn ngành, chuẩn bị hồ sơ đến khi học viên sẵn sàng nhập học.","experts":[{"bio":"Tập trung đánh giá năng lực, sở thích và mục tiêu dài hạn để giúp học viên chọn ngành phù hợp.","name":"Ths. Nguyễn Thu Hương","role":"Chuyên gia định hướng ngành học","experience":"Kinh nghiệm tư vấn lộ trình học nghề quốc tế và định hướng nghề nghiệp sau tốt nghiệp."},{"bio":"Đồng hành cùng học viên từ bước rà soát điều kiện đến hoàn thiện hồ sơ nhập học và visa.","name":"Ông Lê Quang Vinh","role":"Chuyên gia hồ sơ & tuyển sinh","experience":"Kinh nghiệm xử lý hồ sơ tuyển sinh, thủ tục du học và chuẩn bị trước khi xuất cảnh."},{"bio":"Hỗ trợ học viên chuẩn bị ngôn ngữ, kỹ năng thích nghi và kế hoạch học tập tại Trung Quốc.","name":"Cô Phạm Minh Anh","role":"Chuyên gia đồng hành học viên","experience":"Kinh nghiệm đào tạo kỹ năng tiền du học và hỗ trợ học viên trong quá trình hòa nhập."}],"galleryHeading":"Hình ảnh thực tế: visa, trường học & ký túc xá","galleryDescription":"Ảnh từ các khóa học viên đã bay và trường đối tác tại Trung Quốc.","galleryCaptions":["Visa du học sinh đã được cấp cho học viên khóa gần nhất","Khuôn viên trường Cao đẳng nghề đối tác tại Trung Quốc","Phòng ký túc xá trong trường — miễn 100% phí ở","Học viên lên đường nhập học kỳ tháng 9"],"testimonialsHeading":"Học viên đi trước nói gì","testimonials":[{"meta":"Ngành Ô tô điện · Quảng Châu · khóa tháng 9","name":"Nguyễn Văn Hùng","text":"Trước em làm xưởng gỗ 7 triệu/tháng. Sang đây vừa học vừa làm được hơn 20 triệu, tháng nào cũng gửi về nhà 10 triệu. Tay nghề lên hẳn vì được làm trên xe thật.","avatarUrl":""},{"meta":"Ngành Thương mại điện tử · Nghĩa Ô","name":"Trần Thị Ngọc","text":"Em không biết tiếng Hán, được học nền tảng trước khi bay nên sang không bị choáng. Giờ em phụ trách livestream cho một shop, thu nhập ổn định.","avatarUrl":""},{"meta":"Ngành Drone (UAV) · Thâm Quyến","name":"Lê Đình Phúc","text":"Nhà em không đủ tiền cho đi du học tự túc. Chương trình 0Đ giúp em học ngành công nghệ mà chi phí ban đầu rất nhẹ. Ra trường có bằng Cao đẳng chính quy.","avatarUrl":""}],"stepsHeading":"Lộ trình 4 bước đơn giản","steps":[{"title":"Đăng ký & tư vấn 1:1","number":"01","description":"Điền form, chuyên viên gọi lại trong 30 phút, gửi lộ trình chi tiết."},{"title":"Chọn ngành & xét hồ sơ","number":"02","description":"Chọn 1 trong 8 ngành hot, hoàn thiện hồ sơ theo hướng dẫn từng bước."},{"title":"Học tiếng Hán & định hướng","number":"03","description":"Đào tạo tiếng Hán nền tảng và kỹ năng trước khi bay."},{"title":"Nhập học & bắt đầu kiếm tiền","number":"04","description":"Sang trường đối tác, học nghề và làm việc có lương ngay từ kỳ đầu."}],"faqHeading":"Câu hỏi thường gặp","faqs":[{"slug":"hoc_phi","answer":"Có. Học phí được doanh nghiệp Trung Quốc tài trợ theo chương trình liên kết đào tạo nhân lực. Học viên chỉ cần chuẩn bị chi phí hồ sơ, vé máy bay và sinh hoạt ban đầu; phần này được tư vấn minh bạch trước khi đăng ký.","question":"Du học nghề Trung Quốc học phí 0Đ có thật không?"},{"slug":"tieng_trung","answer":"Tốt nghiệp THPT (hoặc tương đương), độ tuổi 18-28, sức khỏe tốt. Không cần chứng minh tài chính và không yêu cầu biết tiếng Hán trước — học viên được đào tạo tiếng Hán nền tảng trước khi bay.","question":"Điều kiện tham gia gồm những gì?"},{"slug":"luong_thuc_tap","answer":"Thu nhập thực tập tại doanh nghiệp đối tác thường 15-30 triệu đồng/tháng tùy ngành và ca làm. Mức này đủ trang trải sinh hoạt, ký túc xá và còn dư gửi về gia đình.","question":"Vừa học vừa làm thì lương bao nhiêu và có đủ sống không?"},{"slug":"bang_cap","answer":"Học viên nhận bằng Cao đẳng chính quy của trường tại Trung Quốc, được công nhận quốc tế, có thể ở lại làm việc, học liên thông lên Đại học hoặc về Việt Nam làm cho doanh nghiệp FDI.","question":"Bằng tốt nghiệp có được công nhận không?"},{"slug":"thoi_gian","answer":"Có hai kỳ nhập học mỗi năm: tháng 3 và tháng 9. Từ lúc đăng ký tới khi bay thường 3-5 tháng, gồm xét hồ sơ, học tiếng Hán và làm thủ tục visa.","question":"Thời gian nhập học và quy trình mất bao lâu?"},{"slug":"nganh_hoc","answer":"Công nghệ ô tô điện, công nghệ drone (UAV), IoT và logistics là các ngành tuyển nhiều nhất, đồng thời có mức lương thực tập cao nhất trong 8 ngành của chương trình.","question":"Ngành nào đang cần nhiều nhân lực nhất?"}],"finalCtaHeading":"Đổi 30 giây hôm nay cho 5 năm tới của bạn","finalCtaDescription":"Nhận lộ trình chi tiết, danh sách trường và mức lương thực tế theo từng ngành — hoàn toàn 0Đ."},"fomo":{"enabled":true,"source":"recentLeads","respectReducedMotion":true,"names":["Trần Văn Nam","Nguyễn Thị Hà","Lê Minh Quân","Phạm Thu Trang","Hoàng Văn Dũng","Đỗ Thị Mai","Vũ Đức Anh","Bùi Thanh Tùng","Ngô Thị Lan","Đặng Hữu Phước"],"cities":["Bình Dương","Hà Nội","Bắc Giang","Nghệ An","Thanh Hóa","Hải Phòng","Đồng Nai","Thái Nguyên","Cần Thơ","Đắk Lắk"],"minDelaySec":10,"maxDelaySec":18,"displaySec":5,"position":"left","template":"{name} ({city}) vừa đăng ký nhận tư vấn"},"countdown":{"enabled":true,"slotsLeft":2,"autoDecrement":true,"headline":"suất học bổng miễn 100% KTX tháng này","endMode":"endOfMonth","endDate":""},"floatingContact":{"enabled":true,"hotline":"0900000000","zalo":"https://zalo.me/0900000000","messenger":"","animateHotline":true,"animateMessenger":true},"trafficStats":{"enabled":true,"position":"footer","title":"Thống kê truy cập thông minh","helperText":"Dữ liệu truy cập được gom từ cùng một kho tracking để đồng bộ giữa Analytics, Mini-CRM và Webhook."},"footer":{"logoUrl":"","menuLabel":"Liên kết nhanh","menuLinks":[{"href":"#dang-ky-cuoi","label":"Đăng ký tư vấn"},{"href":"#faq","label":"Câu hỏi thường gặp"}]},"form":{"headline":"Đăng ký nhận tư vấn miễn phí","ctaLabel":"ĐĂNG KÝ NGAY","webhookUrl":"https://hook.us2.make.com/jtwmjkp2t8wrlr4f080ppgc84u3e53aa","redirectUrl":"","rateLimitCount":3,"rateLimitWindowMin":5,"fields":[{"name":"name","type":"text","label":"Họ và tên","required":true,"placeholder":"Nguyễn Văn A"},{"name":"phone","type":"tel","label":"Số điện thoại","required":true,"placeholder":"09xx xxx xxx"},{"name":"email","type":"email","label":"Email (không bắt buộc)","required":false,"placeholder":"email@example.com"},{"name":"city","type":"select","label":"Tỉnh/Thành phố","required":true,"placeholder":"Chọn tỉnh/thành"},{"name":"major","type":"select","label":"Ngành học quan tâm","required":true,"placeholder":"Chọn ngành"}]},"aiAdvisor":{"enabled":true,"vipDeviceRegex":"iPhone (13|14|15|16) Pro|Pro Max|Galaxy S(22|23|24)|Fold|Flip","keyRegions":"Nghệ An|Hà Tĩnh|Quảng Bình|Thanh Hóa|Quảng Ninh|Hải Phòng","fastFillThresholdSec":4,"vipTimeOnPageSec":80,"vipScrollPercent":70,"weightDevice":20,"weightRegion":15,"weightFastFill":15,"weightTimeOnPage":20,"weightScroll":15,"weightReturnVisit":15,"callScriptTemplate":"Chào {name}, em gọi từ chương trình du học nghề Trung Quốc. Em thấy anh/chị ở {city}, quan tâm ngành {major}. Dựa trên hành vi online, em đánh giá khách là {ai_rank} (score {ai_score}). Gợi ý: {sale_advice}"},"webhooks":[],"emailAutomation":{"enabled":false,"provider":"resend","fromEmail":"","notifyEmail":"","resendApiKey":"","gmailClientId":"","gmailClientSecret":"","gmailRefreshToken":"","subject":"Cảm ơn {name} đã đăng ký tư vấn du học nghề Trung Quốc","body":"Chào {name},\n\nCảm ơn bạn đã để lại thông tin. Đội ngũ tư vấn sẽ liên hệ số {phone} trong thời gian sớm nhất.\n\nTrân trọng.","notifySubject":"[Lead mới] {name} — {phone} — {city}","notifyBody":"Lead mới vừa đăng ký:\n\nHọ tên: {name}\nSĐT: {phone}\nTỉnh: {city}\nNgành: {major}\nAI Score: {ai_score}\nNguồn: {source}"},"abTest":{"enabled":false,"split":50,"variantALabel":"Variant A","variantBLabel":"Variant B","variantAHeadline":"","variantBHeadline":"","variantACta":"","variantBCta":""}}'::jsonb, now()) on conflict (id) do update set data = excluded.data, updated_at = excluded.updated_at;
